    while (queue.length > 0) {
        const sz = queue.length;
        const level = [];
        for (let i = 0; i < sz; i++) {
            const curr = queue.shift();
            level.push(curr.val);
            for (const child of curr.children) {
                if (child) queue.push(child);
            }
        }
        result.push(level);
